head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name fn_MajChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_MajChange = function() {
    // 최대주주 합계주식수
    form["sumLgShr"].setValue(fn_SetComma(fn_RmComma(form["lgshrhdCmstkShrs"].getValue()) + fn_RmComma(form["lgshrhdPrefstkShrs"].getValue())));

    // 최대주주 관계자 합계주식수 
    form["sumRelShr"].setValue(fn_SetComma(fn_RmComma(form["lgshrhdRelprnCmstkShrs"].getValue()) + fn_RmComma(form["lgshrhdRelprnPrefstkShrs"].getValue())));

    // 최대주주 보통주 소계  주식수
    form["sumSubCmn"].setValue(fn_SetComma(fn_RmComma(form["lgshrhdCmstkShrs"].getValue()) + fn_RmComma(form["lgshrhdRelprnCmstkShrs"].getValue())));

    // 최대주주 우선주 소계 주식수
    form["sumSubPref"].setValue(fn_SetComma(fn_RmComma(form["lgshrhdPrefstkShrs"].getValue()) + fn_RmComma(form["lgshrhdRelprnPrefstkShrs"].getValue())));

    // 최대주주 보통+우선주 소계 주식수
    form["sumSubTot"].setValue(fn_SetComma(fn_RmComma(form["sumLgShr"].getValue()) + fn_RmComma(form["sumRelShr"].getValue())));
    scwin.fn_TotalChange();
};
/**
 * @method
 * @name fn_Over5Change
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_Over5Change = function() {
    // 5%이상 주식수
    form["sumOver5LgShr"].setValue(fn_SetComma(fn_RmComma(form["ovr5PctCmstkShrs"].getValue()) + fn_RmComma(form["ovr5PctPrefstkShrs"].getValue())));

    // 관계자 합계주식수 
    form["sumOver5RelShr"].setValue(fn_SetComma(fn_RmComma(form["ovr5PctRelprnCmstkShrs"].getValue()) + fn_RmComma(form["ovr5PctRelprnPrefstkShrs"].getValue())));

    // 보통주합계 주식수
    form["sumSubOver5Cmn"].setValue(fn_SetComma(fn_RmComma(form["ovr5PctCmstkShrs"].getValue()) + fn_RmComma(form["ovr5PctRelprnCmstkShrs"].getValue())));

    // 우선주합계 주식수
    form["sumSubOver5Pref"].setValue(fn_SetComma(fn_RmComma(form["ovr5PctPrefstkShrs"].getValue()) + fn_RmComma(form["ovr5PctRelprnPrefstkShrs"].getValue())));

    // 보통+우선주 주식수
    form["sumSubOver5Tot"].setValue(fn_SetComma(fn_RmComma(form["sumSubOver5Cmn"].getValue()) + fn_RmComma(form["sumSubOver5Pref"].getValue())));
    scwin.fn_TotalChange();
};
/**
 * @method
 * @name fn_Over1Change
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_Over1Change = function() {
    // 1%이상 주식수
    form["sumOver1LgShr"].setValue(fn_SetComma(fn_RmComma(form["ovr1PctCmstkShrs"].getValue()) + fn_RmComma(form["ovr1PctPrefstkShrs"].getValue())));

    // 관계자 합계주식수 
    form["sumOver1RelShr"].setValue(fn_SetComma(fn_RmComma(form["ovr1PctRelprnCmstkShrs"].getValue()) + fn_RmComma(form["ovr1PctRelprnPrefstkShrs"].getValue())));

    // 보통주합계 주식수
    form["sumSubOver1Cmn"].setValue(fn_SetComma(fn_RmComma(form["ovr1PctCmstkShrs"].getValue()) + fn_RmComma(form["ovr1PctRelprnCmstkShrs"].getValue())));

    // 우선주합계 주식수
    form["sumSubOver1Pref"].setValue(fn_SetComma(fn_RmComma(form["ovr1PctPrefstkShrs"].getValue()) + fn_RmComma(form["ovr1PctRelprnPrefstkShrs"].getValue())));

    // 보통+우선주 주식수
    form["sumSubOver1Tot"].setValue(fn_SetComma(fn_RmComma(form["sumSubOver1Cmn"].getValue()) + fn_RmComma(form["sumSubOver1Pref"].getValue())));
    scwin.fn_TotalChange();
};
/**
 * @method
 * @name fn_MinChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_MinChange = function() {
    // 소액주주 주식수
    form["sumMinShr"].setValue(fn_SetComma(fn_RmComma(form["minshrhdCmstkShrs"].getValue()) + fn_RmComma(form["minshrhdPrefstkShrs"].getValue())));
    scwin.fn_TotalChange();
};
/**
 * @method
 * @name fn_TotalChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_TotalChange = function() {
    form["sumTotCmnShr"].setValue(fn_SetComma(fn_RmComma(form["sumSubCmn"].getValue()) + fn_RmComma(form["sumSubOver5Cmn"].getValue()) + fn_RmComma(form["sumSubOver1Cmn"].getValue()) + fn_RmComma(form["minshrhdCmstkShrs"].getValue())));
    form["sumTotPrefShr"].setValue(fn_SetComma(fn_RmComma(form["sumSubPref"].getValue()) + fn_RmComma(form["sumSubOver5Pref"].getValue()) + fn_RmComma(form["sumSubOver1Pref"].getValue()) + fn_RmComma(form["minshrhdPrefstkShrs"].getValue())));
    form["sumTotShr"].setValue(fn_SetComma(fn_RmComma(form["sumSubTot"].getValue()) + fn_RmComma(form["sumSubOver5Tot"].getValue()) + fn_RmComma(form["sumSubOver1Tot"].getValue()) + fn_RmComma(form["sumMinShr"].getValue())));
    var totalCount = fn_RmComma(form["sumTotShr"].getValue());
    if (totalCount > 0) {
        form["lgshrhdShrRt"].setValue(Math.round((fn_RmComma(form["sumLgShr"].getValue()) / totalCount) * 10000) / 100);
        form["lgshrhdRelprnShrRt"].setValue(Math.round((fn_RmComma(form["sumRelShr"].getValue()) / totalCount) * 10000) / 100);
        form["ovr5PctShrRt"].setValue(Math.round((fn_RmComma(form["sumOver5LgShr"].getValue()) / totalCount) * 10000) / 100);
        form["ovr5PctRelprnShrRt"].setValue(Math.round((fn_RmComma(form["sumOver5RelShr"].getValue()) / totalCount) * 10000) / 100);
        form["ovr1PctShrRt"].setValue(Math.round((fn_RmComma(form["sumOver1LgShr"].getValue()) / totalCount) * 10000) / 100);
        form["ovr1PctRelprnShrRt"].setValue(Math.round((fn_RmComma(form["sumOver1RelShr"].getValue()) / totalCount) * 10000) / 100);
        form["minshrhdShrRt"].setValue(Math.round((fn_RmComma(form["sumMinShr"].getValue()) / totalCount) * 10000) / 100);
        form["sumSubRt"].setValue(Math.round((fn_RmComma(form["sumSubTot"].getValue()) / totalCount) * 10000) / 100);
        form["sumSubOver5Rt"].setValue(Math.round((fn_RmComma(form["sumSubOver5Tot"].getValue()) / totalCount) * 10000) / 100);
        form["sumSubOver1Rt"].setValue(Math.round((fn_RmComma(form["sumSubOver1Tot"].getValue()) / totalCount) * 10000) / 100);
        form["sumTotRt"].setValue(Math.round((totalCount / totalCount) * 10000) / 100);
    }
};
/**
 * @method
 * @name fn_AllManChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_AllManChange = function() {
    form["sumTotCnt"].setValue(fn_SetComma(fn_RmComma(form["lgshrhdRelprnCnt"].getValue()) + fn_RmComma(form["ovr5PctRelprnCnt"].getValue()) + fn_RmComma(form["ovr1PctRelprnCnt"].getValue()) + fn_RmComma(form["minshrhdCnt"].getValue()) + scwin.fn_SumAllStockHolder()));
};


//최대주주, 5%이상소유주주, 1%이상소유의 성명이 있으면 +1씩 해준다 '등'이기때문에 07-10-16	
/**
 * @method
 * @name fn_SumAllStockHolder
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SumAllStockHolder = function() {
    var ver = 0;
    if (form["lgshrhdNm"].getValue() != '') {
        ver++;
    }
    if (form["ovr5PctOwnrNm"].getValue() != '') {
        ver++;
    }
    if (form["ovr1PctOwnrNm"].getValue() != '') {
        ver++;
    }
    return ver;
};
/**
 * @method
 * @name fn_VcChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_VcChange = function() {
    var totalCount = fn_RmComma(form["sumTotShr"].getValue());
    if (totalCount > 0) {
        form["ventcapShrRt"].setValue(Math.round((eval(fn_RmComma(form["ventcapCmstkShrs"].getValue()) + fn_RmComma(form["ventcapPrefstkShrs"].getValue())) / totalCount) * 10000) / 100);
    }
};
/**
 * @method
 * @name fn_InstInvstChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_InstInvstChange = function() {
    var totalCount = fn_RmComma(form["sumTotShr"].getValue());
    if (totalCount > 0) {
        form["instInvstShrRt"].setValue(Math.round((eval(fn_RmComma(form["instInvstCmstkShrs"].getValue()) + fn_RmComma(form["instInvstPrefstkShrs"].getValue())) / totalCount) * 10000) / 100);
    }
};
/**
 * @method
 * @name fn_EmpstkassoChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EmpstkassoChange = function() {
    var totalCount = fn_RmComma(form["sumTotShr"].getValue());
    if (totalCount > 0) {
        form["empstkassoRto"].setValue(Math.round((eval(fn_RmComma(form["empstkassoGrntShrs"].getValue())) / totalCount) * 10000) / 100);
    }
};
/**
 * @method
 * @name fn_StkoptChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_StkoptChange = function() {
    var totalCount = fn_RmComma(form["sumTotShr"].getValue());
    if (totalCount > 0) {
        form["stkoptRto"].setValue(Math.round((eval(fn_RmComma(form["stkoptGrntShrs"].getValue())) / totalCount) * 10000) / 100);
    }
};
/**
 * @method
 * @name fn_CheckStockOptionRadio
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckStockOptionRadio = function() {
    var ver = form["stkoptYn"].getValue();
    for (var i = 0; i < form["stkoptYn1"].length; i++) {
        if (form["stkoptYn1"][i].getValue() == ver) {
            form["stkoptYn1"][i].setValue(1);
            scwin.fn_StkoptRadioChange();
            break;
        }
    }
};
/**
 * @method
 * @name fn_EmpstkassoRadioChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_EmpstkassoRadioChange = function() {
    return;
    if (form["empstkassoYn1"][1].checked == true) {
        form["empstkassoGrntprnCnt"].setValue("0");
        form["empstkassoGrntShrs"].setValue("0");
        form["empstkassoRto"].setValue("0");
        form["empstkassoGrntprnCnt"].setDisabled(true);
        form["empstkassoGrntShrs"].setDisabled(true);
        form["empstkassoRto"].setDisabled(true);
    } else {
        form["empstkassoGrntprnCnt"].setDisabled(false);
        form["empstkassoGrntShrs"].setDisabled(false);
        form["empstkassoRto"].setDisabled(false);
    }
};
/**
 * @method
 * @name fn_StkoptRadioChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_StkoptRadioChange = function() {
    return;
    if (form["stkoptYn1"][1].checked == true) {
        form["stkoptGrntprnCnt"].setValue("0");
        form["stkoptGrntShrs"].setValue("0");
        form["stkoptRto"].setValue("0");
        form["stkoptGrntprnCnt"].setDisabled(true);
        form["stkoptGrntShrs"].setDisabled(true);
        form["stkoptRto"].setDisabled(true);
    } else {
        form["stkoptGrntprnCnt"].setDisabled(false);
        form["stkoptGrntShrs"].setDisabled(false);
        form["stkoptRto"].setDisabled(false);
    }
};
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function() {
    fn_ObjValueSetComma(form["lgshrhdCmstkShrs"]); //  최대주주보통주주식수                  
    fn_ObjValueSetComma(form["lgshrhdPrefstkShrs"]); //  최대주주우선주주식수                  
    fn_ObjValueSetComma(form["lgshrhdRelprnCnt"]); //  최대주주관계자수                      
    fn_ObjValueSetComma(form["lgshrhdRelprnCmstkShrs"]); //  최대주주관계자보통주주식수            
    fn_ObjValueSetComma(form["lgshrhdRelprnPrefstkShrs"]); //  최대주주관계자우선주주식수            
    fn_ObjValueSetComma(form["ovr5PctCmstkShrs"]); //  5PCT이상보통주주식수                  
    fn_ObjValueSetComma(form["ovr5PctPrefstkShrs"]); //  5PCT이상우선주주식수                  
    fn_ObjValueSetComma(form["ovr5PctRelprnCnt"]); //  5PCT이상관계자수                      
    fn_ObjValueSetComma(form["ovr5PctRelprnCmstkShrs"]); //  5PCT이상관계자보통주주식수            
    fn_ObjValueSetComma(form["ovr5PctRelprnPrefstkShrs"]); //  5PCT이상관계자우선주주식수            
    fn_ObjValueSetComma(form["ovr1PctCmstkShrs"]); //  1PCT이상보통주주식수                  
    fn_ObjValueSetComma(form["ovr1PctPrefstkShrs"]); //  1PCT이상우선주주식수                  
    fn_ObjValueSetComma(form["ovr1PctRelprnCnt"]); //  1PCT이상관계자수                      
    fn_ObjValueSetComma(form["ovr1PctRelprnCmstkShrs"]); //  1PCT이상관계자보통주주식수            
    fn_ObjValueSetComma(form["ovr1PctRelprnPrefstkShrs"]); //  1PCT이상관계자우선주주식수            
    fn_ObjValueSetComma(form["minshrhdCnt"]); //  소액주주수                            
    fn_ObjValueSetComma(form["minshrhdCmstkShrs"]); //  소액주주보통주주식수                  
    fn_ObjValueSetComma(form["minshrhdPrefstkShrs"]); //  소액주주우선주주식수                  
    fn_ObjValueSetComma(form["ventcapCnt"]); //  벤처캐피탈수                          
    fn_ObjValueSetComma(form["ventcapCmstkShrs"]); //  벤처캐피탈보통주주식수                
    fn_ObjValueSetComma(form["ventcapPrefstkShrs"]); //  벤처캐피탈우선주주식수                
    fn_ObjValueSetComma(form["instInvstCnt"]); //  기관투자자수                          
    fn_ObjValueSetComma(form["instInvstCmstkShrs"]); //  기관투자자보통주주식수                
    fn_ObjValueSetComma(form["instInvstPrefstkShrs"]); //  기관투자자우선주주식수                
    fn_ObjValueSetComma(form["empstkassoGrntprnCnt"]); //  우리사주조합부여자수                  
    fn_ObjValueSetComma(form["empstkassoGrntShrs"]); //  우리사주조합부여주식수                
    fn_ObjValueSetComma(form["stkoptGrntprnCnt"]); //  스톡옵션부여자수                      
    fn_ObjValueSetComma(form["stkoptGrntShrs"]); //  스톡옵션부여주식수    

};
/**
 * @method
 * @name fn_RmCommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmCommaValueAll = function() {
    fn_ObjValueResetRmComma(form["lgshrhdCmstkShrs"]); //  최대주주보통주주식수                  
    fn_ObjValueResetRmComma(form["lgshrhdPrefstkShrs"]); //  최대주주우선주주식수                  
    fn_ObjValueResetRmComma(form["lgshrhdShrRt"]); //  최대주주지분율                        
    fn_ObjValueResetRmComma(form["lgshrhdRelprnCnt"]); //  최대주주관계자수                      
    fn_ObjValueResetRmComma(form["lgshrhdRelprnCmstkShrs"]); //  최대주주관계자보통주주식수            
    fn_ObjValueResetRmComma(form["lgshrhdRelprnPrefstkShrs"]); //  최대주주관계자우선주주식수            
    fn_ObjValueResetRmComma(form["lgshrhdRelprnShrRt"]); //  최대주주관계자지분율                  
    fn_ObjValueResetRmComma(form["ovr5PctCmstkShrs"]); //  5PCT이상보통주주식수                  
    fn_ObjValueResetRmComma(form["ovr5PctPrefstkShrs"]); //  5PCT이상우선주주식수                  
    fn_ObjValueResetRmComma(form["ovr5PctShrRt"]); //  5PCT이상지분율                        
    fn_ObjValueResetRmComma(form["ovr5PctRelprnCnt"]); //  5PCT이상관계자수                      
    fn_ObjValueResetRmComma(form["ovr5PctRelprnCmstkShrs"]); //  5PCT이상관계자보통주주식수            
    fn_ObjValueResetRmComma(form["ovr5PctRelprnPrefstkShrs"]); //  5PCT이상관계자우선주주식수            
    fn_ObjValueResetRmComma(form["ovr5PctRelprnShrRt"]); //  5PCT이상관계자지분율                  
    fn_ObjValueResetRmComma(form["ovr1PctCmstkShrs"]); //  1PCT이상보통주주식수                  
    fn_ObjValueResetRmComma(form["ovr1PctPrefstkShrs"]); //  1PCT이상우선주주식수                  
    fn_ObjValueResetRmComma(form["ovr1PctShrRt"]); //  1PCT이상지분율                        
    fn_ObjValueResetRmComma(form["ovr1PctRelprnCnt"]); //  1PCT이상관계자수                      
    fn_ObjValueResetRmComma(form["ovr1PctRelprnCmstkShrs"]); //  1PCT이상관계자보통주주식수            
    fn_ObjValueResetRmComma(form["ovr1PctRelprnPrefstkShrs"]); //  1PCT이상관계자우선주주식수            
    fn_ObjValueResetRmComma(form["ovr1PctRelprnShrRt"]); //  1PCT이상관계자지분율                  
    fn_ObjValueResetRmComma(form["minshrhdCnt"]); //  소액주주수                            
    fn_ObjValueResetRmComma(form["minshrhdCmstkShrs"]); //  소액주주보통주주식수                  
    fn_ObjValueResetRmComma(form["minshrhdPrefstkShrs"]); //  소액주주우선주주식수                  
    fn_ObjValueResetRmComma(form["minshrhdShrRt"]); //  소액주주지분율                        
    fn_ObjValueResetRmComma(form["ventcapCnt"]); //  벤처캐피탈수                          
    fn_ObjValueResetRmComma(form["ventcapCmstkShrs"]); //  벤처캐피탈보통주주식수                
    fn_ObjValueResetRmComma(form["ventcapPrefstkShrs"]); //  벤처캐피탈우선주주식수                
    fn_ObjValueResetRmComma(form["ventcapShrRt"]); //  벤처캐피탈지분율                      
    fn_ObjValueResetRmComma(form["instInvstCnt"]); //  기관투자자수                          
    fn_ObjValueResetRmComma(form["instInvstCmstkShrs"]); //  기관투자자보통주주식수                
    fn_ObjValueResetRmComma(form["instInvstPrefstkShrs"]); //  기관투자자우선주주식수                
    fn_ObjValueResetRmComma(form["instInvstShrRt"]); //  기관투자자지분율                      
    fn_ObjValueResetRmComma(form["empstkassoGrntprnCnt"]); //  우리사주조합부여자수                  
    fn_ObjValueResetRmComma(form["empstkassoGrntShrs"]); //  우리사주조합부여주식수                
    fn_ObjValueResetRmComma(form["empstkassoRto"]); //  우리사주조합비율                      
    fn_ObjValueResetRmComma(form["stkoptGrntprnCnt"]); //  스톡옵션부여자수                      
